package com.hotelmanagement.controller;
import com.hotelmanagement.dto.*; import com.hotelmanagement.entity.User; import com.hotelmanagement.service.UserService; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="*") public class AuthController {
 @Autowired private UserService userService; @Autowired private PasswordEncoder passwordEncoder;
 @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody UserRegistrationDTO dto){try{User u=userService.registerUser(dto);Map<String,Object> r=new HashMap<>();r.put("message","User registered successfully");r.put("username",u.getUsername());r.put("email",u.getEmail());r.put("userId",u.getId());r.put("role",u.getRole());return ResponseEntity.status(HttpStatus.CREATED).body(r);}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody UserLoginDTO dto){try{Optional<User> o=userService.findByUsername(dto.getUsername());if(o.isEmpty()||!passwordEncoder.matches(dto.getPassword(),o.get().getPassword()))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Invalid username or password"));User u=o.get();Map<String,Object> r=new HashMap<>();r.put("message","Login successful");r.put("userId",u.getId());r.put("username",u.getUsername());r.put("email",u.getEmail());r.put("role",u.getRole());return ResponseEntity.ok(r);}catch(Exception e){return ResponseEntity.status(500).body(Map.of("error","Login failed: "+e.getMessage()));}}
}